/*
 * vm_selftest.c
 *
 * Runs the opcode-switch VM (kernels_vm/vm.slang) on the device with small programs and
 * checks the result against a CPU reference:
 *   - a four-term qual with 64-bit arithmetic and NULLs (exact match set)
 *   - a division by zero (the error must name int4div and a row that really errors)
 * The programs use the real FuncOpCode/TypeOpCode numbers taken from xpu_common.h
 * (generated by gen_opcodes.sh), so a numbering mismatch between host and kernel fails here.
 *
 * Expression trees are flattened into the register program the kernel runs: every
 * instruction is {op, dst, a, b, imm_lo, imm_hi}, AND/OR are accumulate-and-jump steps.
 */
#include <inttypes.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "opcodes.inc"			/* TypeOpCode, FuncOpCode (generated from xpu_common.h) */
#include "vm_selftest.h"
#include "kernels_spv.h"

#define ST_NROWS	65536u
#define ST_STRIDE	21u			/* a int4 @0, b int8 @4, f float4 @12, d int4 @16, null bits @20 */
#define ST_OFF_NB	20
#define ST_MAX_REGS	16

/* -------------------------------------------------------------- trees */
typedef struct Node
{
	uint32_t	op, type;
	int			nargs;
	struct Node *args[4];
	int64_t		imm;
	uint32_t	off, col;
} Node;

static Node pool[64];
static int	npool;

static Node *
mk(uint32_t op, int nargs, Node *a, Node *b, Node *c, Node *d)
{
	Node *n = &pool[npool++];

	memset(n, 0, sizeof(*n));
	n->op = op;
	n->nargs = nargs;
	n->args[0] = a; n->args[1] = b; n->args[2] = c; n->args[3] = d;
	return n;
}
static Node *K(uint32_t type, int64_t v)
{
	Node *n = mk(FuncOpCode__ConstExpr, 0, 0, 0, 0, 0);
	n->type = type;
	n->imm = v;
	return n;
}
static Node *V(uint32_t type, uint32_t off, uint32_t col)
{
	Node *n = mk(FuncOpCode__VarExpr, 0, 0, 0, 0, 0);
	n->type = type; n->off = off; n->col = col;
	return n;
}
#define F1(op,a)		mk(FuncOpCode__##op, 1, a, 0, 0, 0)
#define F2(op,a,b)		mk(FuncOpCode__##op, 2, a, b, 0, 0)
#define AND4(a,b,c,d)	mk(FuncOpCode__BoolExpr_And, 4, a, b, c, d)
#define K4(v)			K(TypeOpCode__int4, v)
#define K8(v)			K(TypeOpCode__int8, v)
static Node *KF(float f)
{
	uint32_t bits;
	memcpy(&bits, &f, 4);
	return K(TypeOpCode__float4, bits);
}
#define VA()			V(TypeOpCode__int4, 0, 0)
#define VB()			V(TypeOpCode__int8, 4, 1)
#define VF()			V(TypeOpCode__float4, 12, 2)
#define VD()			V(TypeOpCode__int4, 16, 3)

/* ---------------------------------------------------------- linearizer */
typedef struct { uint32_t op, dst, a, b, lo, hi; } Insn;
static Insn code[256];
static int	ncode;

static int
ins(uint32_t op, uint32_t dst, uint32_t a, uint32_t b, uint32_t lo, uint32_t hi)
{
	if (ncode >= 256 || dst + 2 > ST_MAX_REGS)
		return -1;
	code[ncode] = (Insn){op, dst, a, b, lo, hi};
	return ncode++;
}

static int
emit(const Node *n, uint32_t dst)
{
	int		steps[4], i;

	switch (n->op)
	{
		case FuncOpCode__ConstExpr:
			return ins(n->op, dst, n->type, 0, (uint32_t)n->imm, (uint32_t)((uint64_t)n->imm >> 32));
		case FuncOpCode__VarExpr:
			return ins(n->op, dst, n->type, n->off, n->col, ST_OFF_NB);
		case FuncOpCode__BoolExpr_And:
			if (ins(FuncOpCode__ConstExpr, dst, TypeOpCode__bool, 0, 1, 0) < 0)
				return -1;
			for (i = 0; i < n->nargs; i++)
			{
				if (emit(n->args[i], dst + 1) < 0 ||
					(steps[i] = ins(n->op, dst, dst + 1, 0, 0, 0)) < 0)
					return -1;
			}
			for (i = 0; i < n->nargs; i++)
				code[steps[i]].b = ncode;		/* jump target: end of the expression */
			return 0;
		default:
			if (emit(n->args[0], dst) < 0)
				return -1;
			if (n->nargs == 2 && emit(n->args[1], dst + 1) < 0)
				return -1;
			return ins(n->op, dst, dst, dst + 1, 0, 0);
	}
}

static int
linearize(const Node *root, uint32_t *prog)
{
	ncode = 0;
	if (emit(root, 0) < 0)
		return -1;
	prog[0] = ncode;
	prog[1] = 0;				/* result register */
	memcpy(prog + 2, code, sizeof(Insn) * ncode);
	return 0;
}

/* ------------------------------------------------------------ the data */
typedef struct { int32_t a; int64_t b; float f; int32_t d; int na, nb, nf, nd; } Row;

static void
decode(const uint8_t *r, Row *o)
{
	uint8_t nb = r[ST_OFF_NB];

	memcpy(&o->a, r, 4);
	memcpy(&o->b, r + 4, 8);
	memcpy(&o->f, r + 12, 4);
	memcpy(&o->d, r + 16, 4);
	o->na = nb & 1; o->nb = (nb >> 1) & 1; o->nf = (nb >> 2) & 1; o->nd = (nb >> 3) & 1;
}

static uint64_t rng = 88172645463325252ULL;
static uint64_t rnd(void) { rng ^= rng << 13; rng ^= rng >> 7; rng ^= rng << 17; return rng; }

/* three-valued logic reference of E1:
 *   (b + (int8)a) > 2^30 AND f > 500.0 AND d < 25 AND a > 1000 */
enum { T_F = 0, T_T = 1, T_N = 2 };
static int t_and(int x, int y) { return (x == T_F || y == T_F) ? T_F : (x == T_N || y == T_N) ? T_N : T_T; }
static int
ref1(const Row *r)
{
	int t1 = (r->na || r->nb) ? T_N : ((r->b + (int64_t)r->a) > (1LL << 30));
	int t2 = r->nf ? T_N : (r->f > 500.0f);
	int t3 = r->nd ? T_N : (r->d < 25);
	int t4 = r->na ? T_N : (r->a > 1000);

	return t_and(t_and(t_and(t1, t2), t3), t4);
}

static int
cmp_u32(const void *a, const void *b)
{
	uint32_t x = *(const uint32_t *)a, y = *(const uint32_t *)b;

	return x < y ? -1 : x > y;
}

static int
fail(char *err, size_t errlen, const char *fmt, ...)
{
	va_list		ap;

	va_start(ap, fmt);
	vsnprintf(err, errlen, fmt, ap);
	va_end(ap);
	return -1;
}

/* ----------------------------------------------------------- the test */
int
gpuserv_vm_selftest(gpu_vk_ctx *ctx, char *err, size_t errlen)
{
	gpu_vk_pipeline pl;
	gpu_vk_buffer	rows = {0}, outb = {0}, progb = {0};
	gpu_vk_buffer  *bufs[3] = {&rows, &outb, &progb};
	struct { uint32_t nrows, stride; } pc = {ST_NROWS, ST_STRIDE};
	uint8_t		   *p;
	uint32_t	   *ob;
	uint64_t		nref = 0, nerr_rows = 0;
	uint32_t		k, i;
	int				rc = -1;

	err[0] = '\0';
	if (gpu_vk_pipeline_create(ctx, &pl, kspv_vm_main, kspv_vm_main_len, 3, sizeof(pc)) != 0)
		return fail(err, errlen, "VM kernel rejected by the driver: %s", ctx->err);
	if (gpu_vk_buffer_create(ctx, &rows, (size_t) ST_NROWS * ST_STRIDE + 16, 0) != 0 ||
		gpu_vk_buffer_create(ctx, &outb, sizeof(uint32_t) * (ST_NROWS + 8), 0) != 0 ||
		gpu_vk_buffer_create(ctx, &progb, 65536, 0) != 0)
	{
		fail(err, errlen, "buffer allocation failed: %s", ctx->err);
		goto done;
	}

	/* rows: same layout and NULL rates as the spike's synthetic table */
	p = rows.map;
	for (i = 0; i < ST_NROWS; i++)
	{
		int32_t a = (int32_t)(rnd() & 0x7fffffff);
		int64_t b = (int64_t)(rnd() % (1ULL << 41)) - (1LL << 40);
		float f = (float)(rnd() % 1000000) / 1000.0f;
		int32_t d = (int32_t)(rnd() % 101) - 50;
		uint8_t nb = 0, *r = p + (size_t) i * ST_STRIDE;

		nb |= (rnd() % 100 < 5) ? 1 : 0;
		nb |= (rnd() % 100 < 5) ? 2 : 0;
		nb |= (rnd() % 100 < 5) ? 4 : 0;
		nb |= (rnd() % 100 < 3) ? 8 : 0;
		memcpy(r, &a, 4); memcpy(r + 4, &b, 8); memcpy(r + 12, &f, 4); memcpy(r + 16, &d, 4);
		r[ST_OFF_NB] = nb;
	}

	/* ---- test 1: qual with 64-bit arithmetic and NULLs ---- */
	npool = 0;
	if (linearize(AND4(F2(int8gt, F2(int8pl, VB(), F1(int4_to_int8, VA())), K8(1LL << 30)),
					   F2(float4gt, VF(), KF(500.0f)),
					   F2(int4lt, VD(), K4(25)),
					   F2(int4gt, VA(), K4(1000))),
				  progb.map) != 0)
	{
		fail(err, errlen, "program assembly failed");
		goto done;
	}
	ob = outb.map;
	ob[0] = ob[1] = ob[2] = 0;
	if (gpu_vk_dispatch(ctx, &pl, bufs, &pc, (ST_NROWS + 255) / 256, 1, 1, NULL) != 0)
	{
		fail(err, errlen, "VM dispatch failed: %s", ctx->err);
		goto done;
	}
	qsort(ob + 3, ob[0], 4, cmp_u32);
	for (i = 0, k = 0; i < ST_NROWS; i++)
	{
		Row r;

		decode(p + (size_t) i * ST_STRIDE, &r);
		if (ref1(&r) == T_T)
		{
			if (k >= ob[0] || ob[3 + k] != i)
			{
				fail(err, errlen, "qual: row %u differs from the CPU reference (gpu matched %u rows)", i, ob[0]);
				goto done;
			}
			k++;
		}
	}
	nref = k;
	if (ob[1] != 0 || k != ob[0] || nref == 0)
	{
		fail(err, errlen, "qual: gpu=%u cpu=%" PRIu64 " err=%u", ob[0], nref, ob[1]);
		goto done;
	}

	/* ---- test 2: int4 division, must raise int4div on a row with d = 0 ---- */
	npool = 0;
	if (linearize(F2(int4gt, F2(int4div, VA(), VD()), K4(3)), progb.map) != 0)
	{
		fail(err, errlen, "program assembly failed");
		goto done;
	}
	ob[0] = ob[1] = ob[2] = 0;
	if (gpu_vk_dispatch(ctx, &pl, bufs, &pc, (ST_NROWS + 255) / 256, 1, 1, NULL) != 0)
	{
		fail(err, errlen, "VM dispatch failed: %s", ctx->err);
		goto done;
	}
	for (i = 0; i < ST_NROWS; i++)
	{
		Row r;

		decode(p + (size_t) i * ST_STRIDE, &r);
		nerr_rows += (!r.na && !r.nd && r.d == 0);
	}
	if (nerr_rows == 0 || ob[1] != FuncOpCode__int4div || ob[2] >= ST_NROWS)
	{
		fail(err, errlen, "division: error code %u (want %u), row %u, %" PRIu64 " rows should error",
			 ob[1], (unsigned) FuncOpCode__int4div, ob[2], nerr_rows);
		goto done;
	}
	{
		Row r;

		decode(p + (size_t) ob[2] * ST_STRIDE, &r);
		if (r.na || r.nd || r.d != 0)
		{
			fail(err, errlen, "division: error reported at row %u which does not divide by zero", ob[2]);
			goto done;
		}
	}
	snprintf(err, errlen, "ok: %" PRIu64 " of %u rows matched, int4div error reported", nref, ST_NROWS);
	rc = 0;
done:
	gpu_vk_buffer_destroy(ctx, &rows);
	gpu_vk_buffer_destroy(ctx, &outb);
	gpu_vk_buffer_destroy(ctx, &progb);
	gpu_vk_pipeline_destroy(ctx, &pl);
	return rc;
}
